def icon(name: str, size: int = 20, extra_class: str = "") -> str:
    """Return one inline SVG at the Polaris 20x20 grid.

    Unknown names fall back to a neutral dot rather than raising, so a typo in
    a template degrades instead of taking the page down.
    """
    entry = _PATHS.get(name)
    inner = entry[1] if entry else "<circle cx='10' cy='10' r='2'/>"
    classes = f' class="{extra_class}"' if extra_class else ""
    return (
        f'<svg{classes} width="{size}" height="{size}" viewBox="0 0 20 20" '
        f'fill="currentColor" aria-hidden="true">{inner}</svg>'
    )


def wordmark(size: int = 20) -> str:
    """Shop Ledger's own mark: three bars, a ledger read as a chart.

    A product's identity assets are the one thing a borrowed design system
    does not supply, so this is drawn rather than taken from Polaris.
    """
    return (
        f'<svg class="glyph" width="{size}" height="{size}" viewBox="0 0 20 20" '
        f'fill="currentColor" aria-hidden="true">'
        f'<rect x="2.5" y="8.5" width="3.6" height="9" rx="1.2"/>'
        f'<rect x="8.2" y="2.5" width="3.6" height="15" rx="1.2"/>'
        f'<rect x="13.9" y="11.5" width="3.6" height="6" rx="1.2"/></svg>'
    )
